interface CapabilityListOverlay {
  /** Add these ids to the team default. */
  add?: string[]
  /** Subtract these ids from the team default. */
  remove?: string[]
  /** Replace the team default entirely with this list (wins over add/remove). */
  replace?: string[]
}
