type PluginCapabilitySupport = "supported" | "partial" | "experimental" | "blocked"
type PluginRuntimeKind = "javascript" | "python" | "wasm" | "vscode" | "asset"
type PluginContributionExecution = "host" | "conditional" | Exclude<PluginRuntimeKind, "asset">
interface PluginContributionJavascriptCondition {
  path: string
  equals?: string
}
interface AuthorCapabilityContract {
  id: string
  support: PluginCapabilitySupport
  manifestFields: readonly string[]
  introducedIn: string
  minimumHostVersion: string
}
/**
 * Whether a pure-Python (or hybrid python-backed) plugin can supply this
 * contribution's runtime executor through the `plugin_python_call` seam.
 * Only meaningful for `javascript` / `conditional` execution fields — `host`
 * contributions are plain data and language-agnostic. Absent means
 * `"unsupported"` (JS/React only, e.g. message renderers and tree views).
 */
type PluginContributionPythonExecution = "supported" | "experimental" | "unsupported"
interface PluginManifestContributionContract {
  field: string
  capabilities: readonly string[]
  execution: PluginContributionExecution
  pythonExecution?: PluginContributionPythonExecution
  entryPath?: string
  javascriptWhen?: PluginContributionJavascriptCondition
}
interface PluginRuntimeEntryContract {
  required: readonly string[]
  javascriptEntry: string | null
  javascriptEntryRequiredForContributions: boolean
  requiredAnyOf?: readonly string[]
}
interface PluginPathFieldContract {
  path: string
  runtime: PluginRuntimeKind
  requiredFor: readonly string[]
  executable: boolean
  sentinels?: readonly string[]
}
type PluginApiDataClassification = "public" | "internal" | "sensitive" | "secret"
type PluginApiRisk = "low" | "medium" | "high" | "critical"
interface PluginApiMethodContract {
  id: string
  name: string
  requiredPermissions: readonly string[]
  consentTier: "none" | "policy" | "confirm" | "forbid"
  risk: PluginApiRisk
  idempotent: boolean
  cancellable: boolean
}
interface PluginApiNamespaceContract {
  id: string
  authorPath: string
  type: string
  stability: "stable" | "experimental" | "deprecated"
  introducedIn: string
  runtimes: readonly string[]
  platforms: readonly string[]
  transport: "direct" | "gateway" | "rpc"
  factory: string
  enforcement: "shadow" | "active"
  dataClassification: PluginApiDataClassification
  timeoutMs: number | null
  retry: "never" | "safe" | "idempotent"
  errorPolicy: "preserve" | "normalize"
  lifecycle: "call" | "plugin" | "host"
  methods: readonly PluginApiMethodContract[]
}
declare const PLUGIN_CONTRACT_SCHEMA_VERSION: number
declare const PLUGIN_CONTRACT_MINIMUM_HOST_VERSION: string
declare const CANONICAL_PLUGIN_TYPES: readonly string[]
declare const CANONICAL_PLUGIN_PERMISSIONS: readonly string[]
declare const PLUGIN_API_NAMESPACE_CONTRACTS: readonly PluginApiNamespaceContract[]
declare const AUTHOR_CAPABILITY_CONTRACTS: readonly AuthorCapabilityContract[]
declare const PLUGIN_PATH_FIELD_CONTRACTS: readonly PluginPathFieldContract[]
declare const PLUGIN_MANIFEST_CONTRIBUTIONS: readonly PluginManifestContributionContract[]
declare const PLUGIN_RUNTIME_ENTRY_CONTRACTS: Readonly<Record<string, PluginRuntimeEntryContract>>
declare const CANONICAL_PLUGIN_CAPABILITIES: string[]

