/**
 * Soft upper bound on characters per pack — keeps the in-memory overlay
 * cost predictable. See ADR-0030 §Risks: 50 × 10 KB systemPrompt = 500 KB
 * per plugin, which is acceptable but should not creep upward silently.
 */
declare const PLUGIN_CHARACTER_PACK_SOFT_LIMIT = 50
/**
 * Soft limit on `avatarImage.webDataUrl` length (~64 KB after base64
 * inflation). Crossing this prints a warning but does NOT block — the
 * runtime overlay budget cited in ADR-0030 §Risks is 500 KB per plugin
 * and a single 64 KB avatar already consumes a sizable share. Authors
 * should ship `tauriPath` references for anything larger.
 */
declare const PLUGIN_CHARACTER_AVATAR_WEB_DATA_URL_SOFT_BYTES: number
declare function defineCharacterPack(def: PluginCharacterPackDef): PluginCharacterPackDef

/**
 * Plugin SDK helper for the `workflow-template` capability.
 *
 * Pure typesafety pass-through — wrapping a manifest entry in
 * `defineWorkflowTemplate()` gives plugin authors autocomplete and a
 * compile-time check that the def shape matches `PluginWorkflowTemplateDef`,
 * including the `requires` block (skill / mcp-preset / native-tool / subagent
 * ids + plugin node/trigger kinds).
 *
 * Usage:
 *   const tpl = defineWorkflowTemplate({
 *     id: "fetch-and-summarize",
 *     name: "Fetch & summarize",
 *     description: "HTTP GET → AI summary → Slack",
 *     category: "automation",
 *     nodes: [...],
 *     edges: [...],
 *     requires: { skillIds: ["my-plugin:summarize"] },
 *   })
 */

declare function defineWorkflowTemplate(def: PluginWorkflowTemplateDef): PluginWorkflowTemplateDef

/**
 * Plugin SDK helper for an inline Agent SDK tool.
 *
 * Pure typesafety pass-through — wrapping a tool in `defineAgentTool()` gives
 * plugin authors autocomplete and a compile-time check against
 * `PluginAgentToolInput` (the shape accepted by `ctx.agent.run({ tools })`).
 *
 * Usage:
 *   const fetchTool = defineAgentTool({
 *     name: "web_fetch",
 *     description: "Fetch a URL and return the body.",
 *     parameters: { type: "object", properties: { url: { type: "string" } } },
 *     execute: async ({ url }) => fetch(String(url)).then((r) => r.text()),
 *     canUseTool: createPiiRedactionGate(),
 *   })
 */

declare function defineAgentTool(tool: PluginAgentToolInput): PluginAgentToolInput

